function transform(text) {
  return ((text2) => toList(text2, true))(text);
}

function toList(text, ordered) {
  let index = 0;
  return text.split(/\r?\n/).map((line) => {
    if (!line.trim())
      return "";
    const content = line.trim().replace(/^(?:[-*+]\s+|\d+[.)、]\s+)/, "");
    return (ordered ? String(++index) + ". " : "- ") + content;
  }).join("\n");
}

